import { Tooltip, Button, TextField } from "@mui/material";
import { Fragment, useContext, useState, useRef, useEffect, useCallback } from "react";
import data from "./DataMap-PH";
import "../../stylesheets/worldmap.scss";
import { MapContext } from "../../contexts/MapContext";
import { ActionTypes } from "../../hooks/Reducer";
import Navbar from "../../components/Navbar";
import { toPng } from 'html-to-image';

const USMap = () => {
  const { state, dispatch } = useContext(MapContext);
  const [phcity, setPHCity] = useState();
  const inputRef = useRef<HTMLInputElement>(null!)
  const ref = useRef<HTMLDivElement>(null!);

  useEffect(() => {
    inputRef.current.focus();
  }, [])

  const onButtonClick = useCallback(() => {
    if (ref.current === null) {
      return
    }

    toPng(ref.current, { cacheBust: true, })
      .then((dataUrl) => {
        const link = document.createElement('a')
        link.download = 'my-phmap.png'
        link.href = dataUrl
        link.click()
      })
      .catch((err) => {
        console.log(err)
      })
  }, [ref])

  const clickHandler = (
    e: any,
    id: string,
    title: string,
    region: string,
  ) => {
    // console.log(e);
    if (e.target.attributes[2].nodeValue === "green") {
      e.target.attributes[2].nodeValue = "#242424";
      dispatch({
        type: ActionTypes.PROV_UNVISITED,
        payload: { title: title },
      });
    } else {
      e.target.attributes[2].nodeValue = "green";
      dispatch({
        type: ActionTypes.PROV_VISITED,
        payload: { id: id, title: title, region: region },
      });
    }
  };

  const submitHandler = (e: any) => {
    e.preventDefault();
    for (let i = 0; i < state.ph_cities.length; i++) {
      if (state.ph_cities[i].title === phcity) {
        dispatch({ type: ActionTypes.PROV_UNVISITED, payload: { title: state.ph_cities[i].title } });
      }
    }

    for (let i = 0; i < data.length; i++) {
      if (data[i].title === phcity) {
        dispatch({ type: ActionTypes.PROV_VISITED, payload: { id: data[i].id, title: data[i].title, region: data[i].region } });
      }
    }
  };

  return (
    <>
      <Navbar />
      <div className="worldmap__container" ref={ref}>
        <svg
          viewBox="0 0 702.39001 1209.4381"
          xmlns="http://www.w3.org/2000/svg"
        >
          {data.map((el, idx) => {
            for (let i = 0; i < state.ph_cities.length; i++) {
              if (state.ph_cities[i].title === el.title) {
                return (
                  <Fragment key={idx}>
                    <Tooltip title={el.title}>
                      <g>
                        <path
                          d={el.d}
                          id={el.id}
                          fill="green"
                          onClick={(e) =>
                            clickHandler(e, el.id, el.title, el.region)
                          }
                        />
                      </g>
                    </Tooltip>
                  </Fragment>
                );
              }
            }
            return (
              <Fragment key={idx}>
                <Tooltip title={el.title}>
                  <g>
                    <path
                      d={el.d}
                      id={el.id}
                      fill="#242424"
                      onClick={(e) =>
                        clickHandler(e, el.id, el.title, el.region)
                      }
                    />
                  </g>
                </Tooltip>
              </Fragment>
            );
          })}
        </svg>
      </div>
      <div className="input">
        <form onSubmit={(e) => submitHandler(e)}>
          <input
            placeholder="Please input a city..."
            onChange={(e: any) => setPHCity(e.target.value.charAt(0).toUpperCase() + e.target.value.slice(1))}
            ref={inputRef}
          />
					<Button variant="contained" size="small" sx={{ backgroundColor: 'green'}} onClick={(e) => submitHandler(e)} >Enter</Button>`
        </form>
        <Button variant="contained" onClick={onButtonClick} id="saveImg" sx={{ marginTop: '10px'}}>Save Map</Button>
      </div>
    </>
  );
};

export default USMap;

